<script setup lang="ts">
import { ref } from 'vue'
const token=ref(localStorage.getItem('admin_token')||'');const username=ref('');const password=ref('');const page=ref('工作台');const merchants=ref<any[]>([]);const users=ref<any[]>([]);const roles=ref<any[]>([]);const permissions=ref<any[]>([]);const logs=ref<any[]>([]);const profile=ref<any>({});const error=ref('');const newMerchant=ref({name:'',type:'THIRD_PARTY'});const newName=ref('');const newPassword=ref('');const newEmail=ref('');const newStatus=ref('ACTIVE');const selectedRole=ref('');const newRoleCode=ref('');const newRoleName=ref('');const selectedPermissions=ref<string[]>([]);const oldPassword=ref('');const password2=ref('')
async function api(path:string,method='GET',body?:any){return fetch(path,{method,headers:{Authorization:`Bearer ${token.value}`,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})}
async function login(){error.value='';const r=await fetch('/api/v1/admin/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});const j=await r.json();if(!r.ok){error.value=j.error?.message||j.detail||'登录失败';return};token.value=j.data.access_token;localStorage.setItem('admin_token',token.value);await load()}
async function load(){try{if(page.value==='商家档案'){const r=await api('/api/v1/admin/merchants');if(r.ok)merchants.value=(await r.json()).data}
if(page.value==='用户管理'){const r=await api('/api/v1/admin/users');if(r.ok)users.value=(await r.json()).data}
if(page.value==='角色权限'){const [a,b]=await Promise.all([api('/api/v1/admin/roles'),api('/api/v1/admin/permissions')]);if(a.ok)roles.value=(await a.json()).data;if(b.ok)permissions.value=(await b.json()).data}
if(page.value==='登录日志'||page.value==='操作日志'){const r=await api(page.value==='登录日志'?'/api/v1/admin/login-logs':'/api/v1/admin/audit-logs');if(r.ok)logs.value=(await r.json()).data}
if(page.value==='个人资料'){const r=await api('/api/v1/admin/me/profile');if(r.ok){profile.value=(await r.json()).data;newName.value=profile.value.display_name}}
}catch(e){error.value='加载失败'}}
function goto(p:string){page.value=p;load()}
async function createMerchant(){const r=await api('/api/v1/admin/merchants','POST',newMerchant.value);if(r.ok){newMerchant.value={name:'',type:'THIRD_PARTY'};load()}else error.value='创建商家失败'}
async function toggleUser(u:any){const status=u.status==='ACTIVE'?'DISABLED':'ACTIVE';const r=await api(`/api/v1/admin/users/${u.id}/status`,'PATCH',{status});if(r.ok)load()}
async function selectRole(id:string){selectedRole.value=id;const r=await api(`/api/v1/admin/roles/${id}/permissions`);selectedPermissions.value=r.ok?(await r.json()).data.permission_ids:[]}
async function saveRole(){if(!selectedRole.value)return;const r=await api(`/api/v1/admin/roles/${selectedRole.value}/permissions`,'PUT',{permission_ids:selectedPermissions.value});if(!r.ok)error.value='权限更新失败'}
async function changePassword(){const r=await api('/api/v1/auth/change-password','POST',{old_password:oldPassword.value,new_password:password2.value});if(r.ok){error.value='密码已修改，请重新登录';logout()}else error.value='密码修改失败'}
async function saveProfile(){const r=await api('/api/v1/admin/me/profile','PATCH',{display_name:newName.value});if(r.ok)profile.value=(await r.json()).data;else error.value='保存失败'}
async function logout(){await api('/api/v1/auth/logout','POST').catch(()=>{});localStorage.removeItem('admin_token');token.value='';page.value='工作台'}
if(token.value)load()
</script>
<template><main v-if="!token" class="login"><h1>平台管理后台</h1><el-input v-model="username" placeholder="管理员账号"/><el-input v-model="password" type="password" show-password placeholder="密码" @keyup.enter="login"/><el-button type="primary" @click="login">登录</el-button><p>{{error}}</p></main><el-container v-else class="layout"><el-aside width="220px"><h2>电商平台</h2><el-menu :default-active="page" @select="goto"><el-menu-item index="工作台">工作台</el-menu-item><el-menu-item index="用户管理">用户管理</el-menu-item><el-menu-item index="角色权限">角色权限</el-menu-item><el-menu-item index="商家档案">商家档案</el-menu-item><el-menu-item index="登录日志">登录日志</el-menu-item><el-menu-item index="操作日志">操作日志</el-menu-item><el-menu-item index="个人资料">个人资料 / 修改密码</el-menu-item></el-menu><el-button @click="logout">退出登录</el-button></el-aside><el-container><el-header>{{page}}<span class="right">平台管理员</span></el-header><el-main><h1>{{page}}</h1><p class="error">{{error}}</p><template v-if="page==='工作台'"><el-card>Phase 2 基础工作台。商品交易、购物车、支付、退款与财务功能未实现。</el-card></template>
<template v-else-if="page==='商家档案'"><el-form inline><el-form-item label="商家名称"><el-input v-model="newMerchant.name"/></el-form-item><el-form-item label="类型"><el-select v-model="newMerchant.type"><el-option label="第三方商家" value="THIRD_PARTY"/><el-option label="平台自营" value="PLATFORM_SELF"/></el-select></el-form-item><el-button type="primary" @click="createMerchant">创建档案</el-button></el-form><el-table :data="merchants"><el-table-column prop="name" label="商家名称"/><el-table-column prop="type" label="类型"/><el-table-column prop="status" label="状态"/><el-table-column prop="review_status" label="审核状态"/></el-table></template>
<template v-else-if="page==='用户管理'"><el-table :data="users"><el-table-column prop="email" label="邮箱"/><el-table-column prop="display_name" label="昵称"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button size="small" @click="toggleUser(s.row)">{{s.row.status==='ACTIVE'?'禁用':'启用'}}</el-button></template></el-table-column></el-table></template>
<template v-else-if="page==='角色权限'"><el-select :model-value="selectedRole" placeholder="选择角色" @change="selectRole"><el-option v-for="r in roles" :key="r.id" :label="r.name+' ('+r.code+')'" :value="r.id"/></el-select><el-checkbox-group v-model="selectedPermissions"><el-checkbox v-for="p in permissions" :key="p.id" :label="p.id">{{p.name}}</el-checkbox></el-checkbox-group><el-button type="primary" @click="saveRole">保存角色权限</el-button><el-divider/><el-table :data="roles"><el-table-column prop="name" label="角色"/><el-table-column prop="scope" label="作用域"/><el-table-column prop="merchant_id" label="商家范围"/></el-table></template>
<template v-else-if="page==='登录日志'||page==='操作日志'"><el-table :data="logs"><el-table-column prop="action" label="事件"/><el-table-column prop="actor_id" label="操作者"/><el-table-column prop="success" label="成功"/><el-table-column prop="request_id" label="请求 ID"/><el-table-column prop="created_at" label="时间"/></el-table></template>
<template v-else-if="page==='个人资料'"><el-form label-width="120px"><el-form-item label="用户名"><el-input :model-value="profile.username" disabled/></el-form-item><el-form-item label="显示名称"><el-input v-model="newName"/></el-form-item><el-button @click="saveProfile">保存资料</el-button><el-divider/><el-form-item label="当前密码"><el-input v-model="oldPassword" type="password"/></el-form-item><el-form-item label="新密码"><el-input v-model="password2" type="password"/></el-form-item><el-button type="danger" @click="changePassword">修改密码</el-button></el-form></template>
</el-main></el-container></el-container></template>
